// Recebe os dados enviados automaticamente pelo Error Trigger.
// Mantemos somente uma descrição curta: nunca propagamos payloads, tokens ou dados pessoais.
const entrada = $('Error Trigger').first().json;
const erro = entrada.execution?.error ?? entrada.error ?? {};

return [{
  json: {
    codigo: 'ERRO_REDACTADO_AGUARDANDO_TELEMETRIA',
    workflow_origem: String(entrada.workflow?.name ?? ''),
    node_origem: String(entrada.lastNodeExecuted ?? ''),
    mensagem: String(erro.message ?? erro.name ?? 'Erro sem descrição').slice(0, 500)
  }
}];
